; DMA controller port tables of the Sound Blaster driver.
; generated by tools/build/gen_src.py, assembled by ./build.sh (see docs/ASM_BUILD.md)
bits 32
%include "hockey.inc"
section s_100000 progbits alloc noexec write align=1
global SbDmaPagePorts, SbDmaMaskPorts, SbDmaModePorts, SbDmaFlipFlopPorts, SbDmaAddressPorts, SbDmaCountPorts
